<template>
  <!-- eslint-disable vue/no-v-html -- markup of the generated icon set, no user input -->
  <svg
    class="antares-icon"
    viewBox="0 0 24 24"
    :width="size"
    :height="size"
    aria-hidden="true"
    v-html="content"
  />
</template>

<script setup lang="ts">
/**
 * An icon of the Antares app, drawn like src/renderer/libs/icons in the antares repo.
 * Names: `table`, `table+cog` (glyph + badge), `table+off`, `brand:docker`.
 * The icon set comes from icons.json, generated by `node scripts/iconKit.js` in the antares repo.
 */
import { computed, useId } from 'vue'
import icons from '~/libs/themeEditor/icons.json'

const props = defineProps({
  name: { type: String, required: true },
  size: { type: [Number, String], default: 18 }
})

const glyphs = icons.glyphs as Record<string, string>
const badges = icons.badges as Record<string, string>
const brands = icons.brands as Record<string, string>

// Each icon has its own mask (ids unique to this instance): Chromium renders a mask shared by SVGs
// of different sizes at the scale of one of them
const maskId = `${useId()}-cut`

const maskMarkup = (content: string) =>
  `<defs><mask id="${maskId}" maskUnits="userSpaceOnUse" x="-4" y="-4" width="32" height="32">`
  + '<rect x="-4" y="-4" width="32" height="32" fill="#fff"/>'
  + `<g fill="#000" stroke="#000" stroke-width="${icons.cutStroke}" stroke-linecap="round" stroke-linejoin="round">${content}</g>`
  + '</mask></defs>'

const content = computed(() => {
  if (props.name.startsWith('brand:')) {
    const path = brands[props.name.slice(6)]
    return path ? `<path class="d" d="${path}"/>` : ''
  }

  const [glyph, modifier] = props.name.split('+')
  if (!glyphs[glyph]) return ''
  if (!modifier) return glyphs[glyph]
  if (modifier === 'off') {
    return maskMarkup(`<path fill="none" stroke-width="${icons.offCutStroke}" d="${icons.offSlash}"/>`)
      + `<g mask="url(#${maskId})">${glyphs[glyph]}</g><path d="${icons.offSlash}"/>`
  }
  if (!badges[modifier]) return ''
  return maskMarkup(badges[modifier])
    + `<g mask="url(#${maskId})">${glyphs[glyph]}</g><g class="b">${badges[modifier]}</g>`
})
</script>

<style>
.antares-icon {
  flex: none;
  overflow: visible;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.25;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.antares-icon .f,
.antares-icon .t {
  fill: currentColor;
  fill-opacity: 0.26;
}

.antares-icon .d {
  fill: currentColor;
  stroke: none;
}

.antares-icon .b {
  color: var(--icon-badge-color, inherit);
}
</style>
